INSERT INTO grade (numgrade)
VALUES (6), (7), (8), (9)
ON CONFLICT (numgrade) DO NOTHING;

INSERT INTO branch (name, code)
VALUES ('Phân hiệu 1', 'A'), ('Phân hiệu 2', 'B')
ON CONFLICT (code) DO NOTHING;

-- =====================================================================================
-- PHẦN 2. DỮ LIỆU GIAI ĐOẠN ĐẦU
-- (khối và phân hiệu đã thêm ở cuối phần 1)
-- =====================================================================================

-- Hash mật khẩu bcrypt bằng crypt(..., gen_salt('bf', 10)) → '$2a$', thư viện bcryptjs verify được
CREATE EXTENSION IF NOT EXISTS pgcrypto;

BEGIN;

-- Lớp và GVCN: (khối, mã phân hiệu, số thứ tự, tên GVCN)
-- Lớp đang học đã tồn tại thì bỏ qua (không đổi GVCN hiện tại)
-- "Trần Thị Ngọc Hà" chủ nhiệm cả 6A2 và 7A4 trong danh sách gốc; class_teacher_unique chỉ cho 1 GV
-- chủ nhiệm 1 lớp nên tạo 2 bản ghi giáo viên trùng tên
CREATE TEMP TABLE init_class (numgrade int, branchcode char(1), seq int, teachername varchar(25)) ON COMMIT DROP;
INSERT INTO init_class VALUES
    (6, 'A', 1, 'Lê Thị Hương Lan'),
    (6, 'A', 2, 'Trần Thị Ngọc Hà'),
    (6, 'A', 3, 'Vũ Thị Thu Hà'),
    (6, 'A', 4, 'Nguyễn Thị Thuỳ Loan'),
    (6, 'A', 5, 'Nguyễn Thị Mỹ Nhung'),
    (6, 'A', 6, 'Hoàng Thị Diệu Thuý'),
    (6, 'A', 7, 'Lê Lan Anh'),
    (6, 'A', 8, 'Trần Thị Mai'),
    (6, 'B', 1, 'Phan Thị Vân'),
    (6, 'B', 2, 'Nguyễn Thị Giang Thuý'),
    (6, 'B', 3, 'Nguyễn Thị Minh Trang'),
    (6, 'B', 4, 'Nguyễn Thị Huyền Trang'),
    (6, 'B', 5, 'Nguyễn Thị Phương Thanh'),
    (7, 'A', 1, 'Trần Thị Hoài Linh'),
    (7, 'A', 2, 'Nguyễn Thùy Linh'),
    (7, 'A', 3, 'Lê Thị Thanh Hà'),
    (7, 'A', 4, 'Trần Thị Ngọc Hà'),
    (7, 'A', 5, 'Trần Thị Kim Châu'),
    (7, 'A', 6, 'Nguyễn Thị Hải Linh'),
    (7, 'A', 7, 'Võ Phi Long'),
    (7, 'A', 8, 'Trần Quang Hiệp'),
    (7, 'A', 9, 'Đặng Thị Diệu Trang'),
    (7, 'B', 1, 'Nguyễn Thị Thuỳ Linh'),
    (7, 'B', 2, 'Nguyễn Trần Thanh Châu'),
    (7, 'B', 3, 'Lê Hồ Thúy Ngân'),
    (7, 'B', 4, 'Nguyễn Thị Kiều Oanh'),
    (7, 'B', 5, 'Bùi Thị Hồng Lê'),
    (8, 'A', 1, 'Nguyễn Thị Thanh Phượng'),
    (8, 'A', 2, 'Trần Minh Tân'),
    (8, 'A', 3, 'Trần Thị Nhã Trúc'),
    (8, 'A', 4, 'Trần Thị Hương Giang'),
    (8, 'A', 5, 'Trần Thị Diệu Hiền'),
    (8, 'A', 6, 'Hoàng Thị Thúy Kiều'),
    (8, 'A', 7, 'Đoàn Thị Thùy'),
    (8, 'A', 8, 'Phạm Sỹ Điểu'),
    (8, 'B', 1, 'Lê Thị Thanh Thủy'),
    (8, 'B', 2, 'Võ Thị Phương'),
    (8, 'B', 3, 'Lê Thị Bảo Na'),
    (8, 'B', 4, 'Trần Thị Ngọc Lan'),
    (8, 'B', 5, 'Đỗ Thị Thủy Tiên'),
    (9, 'A', 1, 'Mai Thị Quý'),
    (9, 'A', 2, 'Nguyễn Thị Vân'),
    (9, 'A', 3, 'Trần Thị Thuỳ Linh'),
    (9, 'A', 4, 'Võ Thị Ái Nhân'),
    (9, 'A', 5, 'Nguyễn Thị Như Huế'),
    (9, 'A', 6, 'Hồ Thị Như Thuỷ'),
    (9, 'A', 7, 'Trần Thị Kiều Liên'),
    (9, 'A', 8, 'Trần Thị Ngọc Anh'),
    (9, 'A', 9, 'Phạm Thị Hồng Lựu'),
    (9, 'B', 1, 'Nguyễn Thị Hà Ly'),
    (9, 'B', 2, 'Lê Thị Thoa'),
    (9, 'B', 3, 'Trần Thị Ánh Huyền'),
    (9, 'B', 4, 'Trần Minh Đăng'),
    (9, 'B', 5, 'Phan Mạnh Hùng'),
    (9, 'B', 6, 'Nguyễn Thị Thu Hiền');

DO $$
DECLARE
    r record;
    newid integer;
BEGIN
    FOR r IN
        SELECT g.id AS gradeid, b.id AS branchid, n.seq, n.teachername
        FROM init_class n
        JOIN grade g  ON g.numgrade = n.numgrade
        JOIN branch b ON b.code = n.branchcode
        WHERE NOT EXISTS (
            SELECT 1 FROM class c
            WHERE c.gradeid = g.id AND c.branchid = b.id AND c.seq = n.seq AND c.archivedyearid IS NULL
        )
        ORDER BY n.numgrade, n.branchcode, n.seq
    LOOP
        INSERT INTO teacher (name, branchid) VALUES (r.teachername, r.branchid) RETURNING id INTO newid;
        INSERT INTO class (seq, gradeid, branchid, teacherid) VALUES (r.seq, r.gradeid, r.branchid, newid);
    END LOOP;
END $$;

