INSERT INTO student (code, name, gender, birthdate, classid)
SELECT n.code, n.name, n.gender, n.birthdate, cv.id
FROM init_student n
JOIN class_view cv ON cv.name = n.classname AND cv.archivedyearid IS NULL
ORDER BY cv.numgrade, cv.branchcode, cv.seq
ON CONFLICT (code) DO NOTHING;

-- Năm học 2026-2027 và 35 tuần (7 ngày liên tiếp từ startdate, điểm gốc 100), chỉ khi chưa có năm học này
WITH sy AS (
    INSERT INTO school_year (name, startdate)
    VALUES ('2026-2027', '2026-09-07')
    ON CONFLICT (name) DO NOTHING
    RETURNING id, startdate
)
INSERT INTO week (schoolyearid, numweek, startdate, enddate)
SELECT sy.id, n, sy.startdate + (n - 1) * 7, sy.startdate + (n - 1) * 7 + 6
FROM sy, generate_series(1, 35) AS n;

-- Tài khoản admin (giáo viên quản lý nề nếp), mật khẩu 1
INSERT INTO account (username, password, role)
VALUES ('admin', crypt('1', gen_salt('bf', 10)), 'admin')
ON CONFLICT (username) DO NOTHING;

COMMIT;

-- Kiểm tra: 55 lớp, 55 GVCN, 2493 học sinh, 35 tuần
SELECT (SELECT COUNT(*) FROM class WHERE archivedyearid IS NULL) AS lop,
       (SELECT COUNT(*) FROM class WHERE archivedyearid IS NULL AND teacherid IS NOT NULL) AS co_gvcn,
       (SELECT COUNT(*) FROM student) AS hoc_sinh,
       (SELECT COUNT(*) FROM week w JOIN school_year sy ON sy.id = w.schoolyearid WHERE sy.name = '2026-2027') AS tuan;
